ALTER TABLE "presentation_editor_snapshots" ADD COLUMN "source_object_version_id" varchar(255);--> statement-breakpoint
ALTER TABLE "presentation_editor_snapshots" ADD COLUMN "source_media_type" varchar(160);--> statement-breakpoint
