ALTER TABLE "presentation_editor_snapshots" ADD CONSTRAINT "presentation_editor_snapshots_source_identity_check" CHECK (("presentation_editor_snapshots"."source_object_key" is null and "presentation_editor_snapshots"."source_object_version_id" is null and "presentation_editor_snapshots"."source_media_type" is null and "presentation_editor_snapshots"."source_size_bytes" is null and "presentation_editor_snapshots"."source_sha256" is null) or ("presentation_editor_snapshots"."source_object_key" is not null and "presentation_editor_snapshots"."source_object_version_id" is not null and "presentation_editor_snapshots"."source_media_type" = 'application/vnd.spectra.presentation-source+json' and "presentation_editor_snapshots"."source_size_bytes" between 1 and 33554432 and "presentation_editor_snapshots"."source_sha256" ~ '^[0-9a-f]{64}$'));